        "raw_body": "# A new OTW\n### February 24, 2026\n\n---\n\nWhere have I heard that before?  Surely, at least five times on this site during the past 26 years.    \n  \n**26 years, btw.**   That's how long I've had this domain registered and operating in one form or another.  I finally felt the drive to really sit down and get all of the accumulated digital cruft organized and back online.  So, what you see is the first stage of the process.  I still haven't quite decided whether I will keep the site divided into Personal/Professional ongoing.  But at this point in time, the \"Personal\" site is mostly online and functional.  \n  \nWith the personal side, you'll find a trove of old data on the right side of the screen, separated into \"cards\". The ones most interesting for visitors will likely be [The Archive] and [The Flotsam], for that is where most of the past has been resurrected and then buried again.    \n  \nYou'll also see a bit of boutique linkage in the form of a limited edition run of OTW t-shirts.  These are pretty fabulous unisex shirts that all your friends will pine over, surely.  Why not grab one?  \n  \nThere is certainly more work to be done over the comings weeks, so stay tuned.  At the very least, the OTW blog will be updated regularly again, so there's that.  \n  \nThanks for visiting!"
