        "file": "2007-08-29-On-the-Trax.md",
        "current_title": "On the trax",
        "year": "2007",
        "date": "08/29",
        "raw_body": "# On the Trax\nDate: August 29, 2007\n\n\nWe find ourselves on the UTA Trax this morning, en route to Salt Lake City.  We figured we'd save the gas and use the train, but my gosh.  $4.25 for an all day pass?  Yeesh.The train is mostly empty now, but it'll fill up quickly as we follow the track.  Sumner doesn't remember doing this a few years ago, which is sad only because the trip with him as an 18 month old is imprinted on my mind so thoroughly.  I'll keep the memory going for him, then.The train started moving now, and I am in the rear facing seat.  It makes me a bit ill to type in this environment, so I bid you adiue for now.  More pictures as the day progresses!"
