        "file": "2007-07-04-We-find-ourselves-in-Chandler-.md",
        "current_title": "We find ourselves in chandler",
        "year": "2007",
        "date": "07/04",
        "raw_body": "# We find ourselves in Chandler again\nDate: July 04, 2007\n\n\nI hadn't posted a picture in a while, and this view fit the bill, so I snapped it.  Now, why are we here?  Silly question.  Because they have a Gap?!  I kid, I kid.  I wanted to show the wife the iPhone.  I think she liked it.  And she could use the keyboard immediately, so she's already ahead of about 56% of the population.  But that figures, right?  She's generally more adaptable than I am.  I'm just too stubborn.  Sumner hasn't woken up since we started for home two hours ago.  This may be one of those nights where he sleeps straight through.  Just as well, cause I've got a massive amount of work to do.  Here's hoping your night is cheery! Posted wirelessly!"
