        "current_title": "Daddy and sumner are solo toda",
        "year": "2007",
        "date": "06/30",
        "raw_body": "# Daddy and Sumner are solo today\nDate: June 30, 2007\n\n\nWife is at work - time for us to go wreak our own brand of havoc upon East freakin' Mesa.Doesn't that look like the face of a boy ready to show people what he's  made of?Posted wirelessly!"
